// Inspect matches and enforce minimum cosine similarity threshold
const question = $('Validate Question Payload').first().json.question;
const rawMatches = $json.matches || [];

// Minimum similarity score threshold for cosine distance
const RELEVANCE_THRESHOLD = parseFloat($env.PINECONE_MIN_RELEVANCE || '0.65');

const relevantMatches = rawMatches.filter(m => (m.score || 0) >= RELEVANCE_THRESHOLD);

if (relevantMatches.length === 0) {
  return [{
    json: {
      question,
      has_sufficient_evidence: false,
      answer: "I do not have sufficient research in the database to answer this question. No indexed articles met the relevance threshold for your query.",
      sources: [],
      insufficient_evidence: true
    }
  }];
}

// Construct grounded context string for Gemini prompt
let contextStr = '';
const sources = [];

relevantMatches.forEach((match, i) => {
  const meta = match.metadata || {};
  contextStr += `[Source ${i + 1}] Title: ${meta.title || 'Untitled'}\n`;
  contextStr += `URL: ${meta.source_url || 'Unknown'}\n`;
  contextStr += `Summary: ${meta.summary || ''}\n`;
  if (Array.isArray(meta.key_points)) {
    contextStr += `Key Points: ${meta.key_points.join('; ')}\n`;
  }
  contextStr += `Similarity Score: ${match.score?.toFixed(3)}\n\n`;

  sources.push({
    title: meta.title || 'Untitled',
    source_url: meta.source_url || '',
    score: match.score
  });
});

return [{
  json: {
    question,
    has_sufficient_evidence: true,
    context: contextStr.trim(),
    sources,
    insufficient_evidence: false
  }
}];

