// Extract answer from Gemini response and assemble final response object
const prior = $('Filter Relevance & Build Context').first().json;
const geminiData = $json;

const answerText = geminiData.candidates?.[0]?.content?.parts?.[0]?.text?.trim() ||
  'Unable to synthesize response from available research context.';

return [{
  json: {
    success: true,
    question: prior.question,
    answer: answerText,
    sources: prior.sources,
    insufficient_evidence: false
  }
}];
